INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "春咲 ひより", 0, "お！\nあそこに困ってそうな人発見！", 0, 1, 1, 0, 0, 1001, "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", "ねぇねぇ、騎士クン\n手伝ってあげようよ～", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "草野 優衣", 0, "大切な人を\n守れるようになりたい…って", 0, 1, 1, 0, 0, 1002, "みんなみたいに\nわたしも強くならなきゃ", "わ、わたし、\nなに言ってるんだろ\nあはは…", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "士条 怜", 0, "キミに必要な集中力と感性が", 0, 1, 1, 0, 0, 1003, "フェンシングを始めてみては？", "少しは磨かれると思いますよ。", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "穂高 みそぎ", 0, "今日はなにして遊ぶ？", 0, 1, 1, 0, 0, 1004, "ねぇ、にいちゃん！", "みそぎはねぇ、\nかくれんぼやりたい！", 1, 0, 1.5);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "風宮 あかり", 0, "ねぇ…", 0, 1, 1, 0, 0, 1006, "風宮あかりです", "私といっしょに…\nいかない？", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "出雲 宮子", 0, "プリンたべたいのー", 0, 1, 1, 0, 0, 1007, "出雲宮子なのー", "食べ物の恨みは怖いのー", 1, 0, 1.5);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "虹村 雪", 0, "キミもボクの美貌に\n吸い寄せられたんだね。", 0, 1, 1, 0, 0, 1008, "ボクは虹村雪。", "いいよ。\n見られることは運命さ…", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "柊杏奈", 0, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", 0, 1, 1, 0, 0, 1009, "フッ…聞いて後悔するがいい！", "人呼んで「疾風の冥姫」!!", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "姫宮 真歩", 0, "うさぎさん、\n運命の王子はんに巡りあわせてくれて", 0, 1, 1, 0, 0, 1010, "マホマホ王国のプリンセス、\nまほ姫どす", "ほんまおおきにやわ～♪", 1, 0, 1.5);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "衣之咲 璃乃", 0, "生き別れたお兄ちゃんを探して\n三千世界！", 0, 1, 1, 0, 0, 1011, "衣之咲璃乃です！", "ここで会ったが\n100年目～！", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "柏崎 初音", 0, "ち、超能力って…\n何のことかな～？", 0, 1, 1, 0, 0, 1012, "私はハツネ、\n結構強いんだよ。\nきらーん☆", "…って、お願い！\n誰にも言わないでおいて～！", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "美波 鈴奈", 0, "一応カリスマ読モJKやってまっす！", 0, 1, 1, 0, 0, 1016, "ちょす！\n美波鈴奈だよ～♪", "ヒデサイまぢ\nGF（グッドフィーリング）～♪", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "喜屋武 香織", 0, "東京は遊園地みたいなところさー", 0, 1, 1, 0, 0, 1017, "はいたーい。\n喜屋武香織さー。", "でも、沖縄もとってもいいとこさー", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "支倉 伊緒", 0, "先生って呼ばれるのは\nくすぐったいから", 0, 1, 1, 0, 0, 1018, "支倉伊緒です。", "イオちゃんって呼んでね。", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "茜 ミミ", 0, "あ！/\お兄ちゃ～ん\nまってよ～", 0, 1, 1, 0, 0, 1020, "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", "ミミをおいてかないでぇ～", 1, 0, 1.5);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "栗林 くるみ", 0, "あの……\nふぇ……", 0, 1, 1, 0, 0, 1021, "あ…あの…えっと…\n栗…林…くるみ…です……", "ふぇぇぇぇぇん……", 1, 0, 1.5);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "風宮 より", 0, "こんな私に貴重な時間を\n割いていただき、", 0, 1, 1, 0, 0, 1022, "風宮よりです。\nあああああ！", "なんてありがとうございます！", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "北条 綾音", 0, "おにいちゃんどこいくの？\nえ？", 0, 1, 1, 0, 0, 1023, "私、アヤネ！\nぷうきちと一緒についてってあげるね！", "私こっち行きたいー\nね、早く早くー", 1, 0, 1.5);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "天野 すずめ", 0, "ふ、不束者ですが\nどうぞ末永く…って、", 0, 1, 1, 0, 0, 1025, "わっ…わっ…私、\n天野すずめといいます！", "これて何か違う…\nあああすみません！", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "倉石 恵理子", 0, "あなたは…運命の……\n伴侶……", 0, 1, 1, 0, 0, 1027, "……クスクス…私は\n…倉石恵理子……", "離しませんわ………\n絶対に…!!", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "佐々木 咲恋", 0, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", 0, 1, 1, 0, 0, 1028, "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", "…そうでしょ？？", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "桜井 望", 0, "ぇっと…\nキミ、私のこと知らないの?!", 0, 1, 1, 0, 0, 1029, "桜井望だよ！\nよろしくねっ", "あはは、\n私もまだまだだなぁ～", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "ニノン・ジュベール", 0, "初めまして、\n私はニノン・ジュベール申すデス！", 0, 1, 1, 0, 0, 1030, "デケデケデンっ！", "ショーグン、\nワタシと一緒に天下統一デース！", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "上喜 しのぶ", 0, "でもって私の隣にいるのが……\nえ、見えない？", 0, 1, 1, 0, 0, 1031, "上喜しのぶです。\n手元のドクロが父です。", "おかしいですね……", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "野戸まひる", 0, "けんども\nそれには足りないモンが…", 0, 1, 1, 0, 0, 1033, "目指すはビッグな\nお笑い芸人だっぺ！", "そう、\nオラのボケに突っ込める相方が…！", 1, 0, 1.5);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "綾瀬 ゆかり", 0, "ちょっと緊張しちゃって…", 0, 1, 1, 0, 0, 1034, "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", "ちょ\nちょっと一杯飲んできます…！", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "氷川 鏡華", 0, "知らない人とは話しちゃいけないので", 0, 1, 1, 0, 0, 1036, "氷川鏡華…です", "これ以上お話しすることは…\nないです！", 1, 0, 1.5);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "柏崎 栞", 0, "……あ、アラーム。", 0, 1, 1, 0, 0, 1038, "柏崎…栞です。", "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "双葉 碧", 0, "私、一人も友達がいなくて……", 0, 1, 1, 0, 0, 1040, "ふ、双葉碧です。", "野に咲く花が、\n唯一の話相手です。", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "三角 千歌", 0, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", 0, 1, 1, 0, 0, 1042, "三角千歌です。", "そう思っています。", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "安芸 真琴", 0, "あぁ？\nお前のそいつの仲間か？", 0, 1, 1, 0, 0, 1043, "安芸真琴だ。", "う、疑ってすまなかったな…", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "イリヤ・オーンスタイン", 0, "生けとし生ける全ての者よ！", 0, 1, 1, 0, 0, 1044, "わらわこそは夜を総べる者！", "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "遠見 空花", 0, "ぐふふふふ……はっ！", 0, 1, 1, 0, 0, 1045, "そこで騎士は妖精を乱暴に……", "ｌク、クウカに何かご用ですか!?", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "宮坂たまき", 0, "自由気ままで♪\n寝て遊んで、食べてケンカして…", 0, 1, 1, 0, 0, 1046, "宮坂たまきにゃ♪\n猫はいいにゃよ？", "う～ん…\n猫ってホントに最高にゃ～♪", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "大神 美冬", 0, "それでは早速クエストに…", 0, 1, 1, 0, 0, 1048, "大神美冬よ！", "…と思ったら\nバイトの時間だ！\nまたあとでね！", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "星野静流", 0, "クエストもバトルも\n掃除も洗濯も", 0, 1, 1, 0, 0, 1049, "星野静流だよ！", "お姉ちゃんがぜ～んぶ\nやってあげるからね！", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "玉泉美咲", 0, "見ての通りの\nセクシー美少女で", 0, 1, 1, 0, 0, 1050, "アタシは玉泉美咲。", "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", 1, 0, 1.5);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "リマ", 0, "？？？？", 0, 1, 1, 0, 0, 1052, "？？？", "？？？？", 1, 0, 1.4);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "モニカ・ヴァイスヴィント", 0, "菓子でつろうなどと\n稚拙な策を……", 0, 1, 1, 0, 0, 1053, "モニカ・ヴァイスヴィントだ。", "そ、そこまでいうなら\nもらってやる", 1, 0, 1.5);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "ペコリーヌ", 0, "菓子でつろうなどと\n稚拙な策を……", 0, 1, 1, 0, 0, 1058, "モニカ・ヴァイスヴィントだ。", "そ、そこまでいうなら\nもらってやる", 1, 0, 1.5);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "コッコロ", 0, "菓子でつろうなどと\n稚拙な策を……", 0, 1, 1, 0, 0, 1059, "モニカ・ヴァイスヴィントだ。", "そ、そこまでいうなら\nもらってやる", 1, 0, 1.5);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (2, "キャル", 0, "菓子でつろうなどと\n稚拙な策を……", 0, 1, 1, 0, 0, 1060, "モニカ・ヴァイスヴィントだ。", "そ、そこまでいうなら\nもらってやる", 1, 0, 1.5);
